"""Lay students out in rows ordered by last name."""

from typing import List

from rosterkit.models import Student


def _sort_key(student: Student):
    last = student.last_name.lower()
    return (last, student.first_name.lower())


def _format_rows(
    ordered: List[Student], width: int
) -> List[str]:
    lines = []
    # one output line per run of `width` students
    for start in range(0, len(ordered), width):
        chunk = ordered[start:start + width]
        names = [item.display_name for item in chunk]
        label = f"Row {start // width + 1}: "
        lines.append(label + " | ".join(names))
    return lines


# ---
def seat_rows(
    students: List[Student], per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    if per_row < 1 or not students:
        raise ValueError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    return _format_rows(ordered, per_row)

