import unittest

from rosterkit.models import Student
from rosterkit.seating import seat_rows


def make(last, first):
    return Student("id-" + last, last, first, "A")


ROSTER = [
    make("Halloway", "Juno"),
    make("Dunmere", "Piet"),
    make("Ames", "Zoe"),
]


class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_fills_rows(self):
        lines = seat_rows(ROSTER, 2)
        self.assertEqual(lines, [
            "Row 1: Ames, Zoe | Dunmere, Piet",
            "Row 2: Halloway, Juno",
        ])

    def test_one_row_when_seats_exceed(self):
        self.assertEqual(len(seat_rows(ROSTER, 10)), 1)

    def test_first_name_breaks_ties(self):
        pair = [make("Lee", "Zed"), make("Lee", "Amy")]
        want = ["Row 1: Lee, Amy | Lee, Zed"]
        self.assertEqual(seat_rows(pair, 2), want)

