import unittest

from rosterkit.models import Student
from rosterkit.seating import seat_rows

ONE = [Student("id-1", "Ames", "Zoe", "A")]


class SeatRowsErrorTests(unittest.TestCase):
    def test_bad_seat_counts_raise(self):
        # zero and negative counts are both rejected
        for bad in (0, -3):
            with self.assertRaises(ValueError):
                seat_rows(ONE, bad)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
